insert into public.templates (template_id, lao_pattern, english_pattern, slot_names, intro_order, requires_word_ids, source, confidence, notes) values
  ('TPL01', '{statement}ບໍ່?', '{statement}? (yes/no question)', 'statement', 1, 'W000003', 'SRC-WIKT:ບໍ່', 'verified', 'Wiktionary ບໍ່ (interrogative): example ດີບໍ່? ''Is it good?''. Questions keep statement word order and add ບໍ່ at the end'),
  ('TPL02', 'ບໍ່{predicate}', 'not {predicate}', 'predicate', 2, 'W000003', 'SRC-WIKT:ບໍ່', 'verified', 'Negation goes before the verb or adjective (Wiktionary ບໍ່: ''no, not'')'),
  ('TPL03', 'ຂໍ{noun}', 'May I have {noun}? / {noun} please', 'noun', 3, 'W000009|W000011', 'SRC-WIKT:ຂໍ', 'unverified', 'Wiktionary glosses ຂໍ ''to ask for, request'' but gives no ຂໍ + noun example; pattern composed by the agent'),
  ('TPL04', '{place}ຢູ່ໃສ?', 'Where is {place}?', 'place', 4, 'W000014|W000015', 'SRC-WIKT:ໃສ;SRC-WIKT:ຢູ່', 'unverified', 'Built from the verified glosses ຢູ່ ''be located'' and ໃສ ''where''; the pattern matches Tatoeba 8975845 ເຮືອນເຈົ້າຢູ່ໃສ?'),
  ('TPL05', '{verb}ແລ້ວບໍ່?', 'Have you {verb} yet?', 'verb', 5, 'W000020|W000003', 'SRC-WIKT:ແລ້ວ', 'unverified', 'ແລ້ວ = completed-action auxiliary (Wiktionary). Pattern composed by the agent'),
  ('TPL06', '{pronoun}ຢາກ{verb}', '{pronoun} want(s) to {verb}', 'pronoun|verb', 6, 'W000022', 'SRC-TATOEBA:8670347', 'verified', 'Tatoeba 8670347 ຂ້ອຍຢາກກິນ ''I want to eat''; 8978757'),
  ('TPL07', '{pronoun}ມີ{noun}', '{pronoun} has/have {noun}', 'pronoun|noun', 7, 'W000023', 'SRC-WIKT:ມີ', 'unverified', 'Built from the verified gloss ມີ ''to have''; pattern composed by the agent'),
  ('TPL08', '{pronoun}ໄປ{place}', '{pronoun} go(es) to {place}', 'pronoun|place', 8, 'W000024', 'SRC-TATOEBA:8975794', 'verified', 'Destination follows ໄປ with no preposition: Tatoeba 8975794 ຂ້ອຍໄປປະເທດລາວ ''I go to Laos'''),
  ('TPL09', '{noun}ນີ້{adjective}', 'This {noun} is {adjective}', 'noun|adjective', 9, 'W000016|W000002', 'SRC-TATOEBA:8981608', 'verified', 'Tatoeba 8981608 ໂຮງແຮມນີ້ແພງ ''This hotel is expensive'''),
  ('TPL10', 'ຂ້ອຍຊື່{name}', 'My name is {name}', 'name', 10, 'W000006|W000041', 'SRC-TATOEBA:13115622', 'verified', 'Tatoeba 13115622 ຂ້ອຍຊື່ທອມ ''My name is Tom''; question form ເຈົ້າຊື່ຫຍັງ? (1897940)'),
  ('TPL11', '{pronoun}ມັກ{thing}', '{pronoun} like(s) {thing}', 'pronoun|thing', 11, 'W000069', 'SRC-TATOEBA:8978767', 'verified', 'Tatoeba 8978767 ແມ່ຂ້ອຍບໍ່ມັກກາເຟນີ້ ''My mother doesn''t like this coffee'''),
  ('TPL12', '{adjective}ຫຼາຍ', 'very {adjective}', 'adjective', 12, 'W000091', 'SRC-TATOEBA:8993577', 'verified', 'Tatoeba 8993577 ລາວຕຸ້ຍຫຼາຍ ''He''s very fat'''),
  ('TPL13', '{pronoun}ຕ້ອງການ{thing}', '{pronoun} need(s) {thing}', 'pronoun|thing', 13, 'W000067', 'SRC-TATOEBA:9356681', 'verified', 'Tatoeba 9356681 ພວກເຮົາຕ້ອງການປະໂຫຍກທີ່ສົມບູນ ''We want complete sentences'''),
  ('TPL14', '{noun}{number}{classifier}', '{number} {noun}(s)', 'noun|number|classifier', 14, 'W000047|W000097', 'SRC-SEASITE', 'verified', 'Noun + number + classifier: SEAsite grammar note 17 ເບຍສອງແກ້ວ ''two bottles of beer''; e.g. ໝາສອງໂຕ ''two dogs'''),
  ('TPL15', '{pronoun}ຢາກສັ່ງ{dish}', '{pronoun} would like to order {dish}', 'pronoun|dish', 15, 'W000022', null, 'unverified', 'Restaurant ordering. Composed by the agent from ຢາກ + verb (TPL06). Needs ສັ່ງ (batch5a) in the pattern; dish fillers include ເຂົ້າຜັດ ເຄື່ອງດື່ມ (batch5a)'),
  ('TPL16', '{item}ນີ້ເທົ່າໃດ?', 'How much is this {item}?', 'item', 16, 'W000016|W000017', null, 'unverified', 'Shopping/prices. Composed by the agent using ເທົ່າໃດ (W000017) and ນີ້ (W000016). Fillers include ຊຸດ ປີ້ (batch5a)'),
  ('TPL17', 'ໄປ{place}ແນວໃດ?', 'How do I get to {place}?', 'place', 17, 'W000024|W000101', null, 'unverified', 'Directions/transport. Composed by the agent from ໄປ + place (TPL08) + ແນວໃດ ''how''. Fillers include ສະຖານີລົດເມ ຮ້ານຢາ (batch5a)'),
  ('TPL18', '{pronoun}{symptom}', '{pronoun} have/has {symptom}', 'pronoun|symptom', 18, 'W000006|W000169', null, 'unverified', 'Health/symptoms. Composed by the agent; symptom is a verb phrase such as ປວດຫົວ ''have a headache'' (no separate verb ''have'' needed). Fillers are from batch5a except ເມື່ອຍ'),
  ('TPL19', 'ຕອນ{time}ຂ້ອຍ{activity}', 'In the {time} I {activity}', 'time|activity', 19, 'W000138|W000006', null, 'unverified', 'Daily routine. Composed by the agent using ຕອນ (W000138) + time of day; activity fillers include ຕື່ນນອນ ຖູແຂ້ວ ລ້າງໜ້າ ເຂົ້ານອນ (batch5a)'),
  ('TPL20', 'ວັນທີ່{number}ເດືອນ{month}', 'The {number}th of {month}', 'number|month', 20, 'W000145|W000147', null, 'unverified', 'Dates. Composed by the agent. Needs ວັນທີ່ (batch5a; spelling ວັນທີ່ vs ວັນທີ to be resolved). Number slot takes a numeral (e.g. ສິບສອງ ຊາວເອັດ); month fillers are batch5a month names'),
  ('TPL21', '{pronoun}ຮູ້ສຶກ{feeling}', '{pronoun} feel(s) {feeling}', 'pronoun|feeling', 21, 'W000498', null, 'unverified', 'Composed by the agent. ຮູ້ສຶກ W000498 + adjective of feeling. Batch words needed: ເບື່ອ ເສົ້າ ຕື່ນເຕັ້ນ ອາຍ (also W000252 ດີໃຈ W000253 ເສຍໃຈ). Examples S000001685 S000001687 S000001689 S000001692'),
  ('TPL22', '{pronoun}ເຮັດວຽກເປັນ{job}', '{pronoun} work(s) as a {job}', 'pronoun|job', 22, 'W000066|W000027', null, 'unverified', 'Composed by the agent. ເຮັດວຽກ W000066 + ເປັນ W000027 + occupation noun. Batch words needed: ຄົນງານ ຜູ້ຈັດການ ພະຍາບານ ຊ່າງ ທະຫານ (also W000156 ຄູ W000162 ໝໍ W000378 ຕຳຫຼວດ). Examples S000001755 S000001764 S000001781 S000001784 S000001788'),
  ('TPL23', '{pronoun}ຢາກຈອງ{thing}', '{pronoun} would like to book {thing}', 'pronoun|thing', 23, 'W000022', null, 'unverified', 'Composed by the agent. ຢາກ W000022 + ຈອງ (batch) + thing booked. Batch words needed: ຈອງ ເຮືອນພັກ (also W000012 ຫ້ອງ W000119 ໂຕະ). Examples S000001808 S000001809 S000001817 S000002011 S000002012'),
  ('TPL24', '{time}ມີ{weather}', 'There is/was/will be {weather} {time}', 'time|weather', 24, 'W000023|W000037', null, 'unverified', 'Composed by the agent. ມີ W000023 used for existence. Time word + ມີ + weather noun. Batch words needed: ຟ້າຮ້ອງ ພາຍຸ ໝອກ ນ້ຳຖ້ວມ (also W000120 ຝົນ W000543 ແດດ W000544 ລົມ W000545 ເມກ). Time fillers W000037 W000038 W000140. Examples S000001874 S000001876 S000001880 S000002006 S000002007 S000002008'),
  ('TPL25', 'ຂ້ອຍບໍ່{verb}ເພາະວ່າຂ້ອຍ{adjective}', 'I am not {verb}ing because I am {adjective}', 'verb|adjective', 25, 'W000003|W000110|W000006', null, 'unverified', 'Composed by the agent. ເພາະວ່າ (batch word) = because; W000110 ເພາະ alone is also known. Reason clause with adjective of state. Batch words needed: ເພາະວ່າ (also W000173 ເມື່ອຍ W000268 ຫຍຸ້ງ W000073 ອີ່ມ; ເບື່ອ from batch). Examples S000001658 S000001659 S000002009 S000002010'),
  ('TPL26', '{noun}{adjective}ກວ່າ{noun}', '{noun} is more {adjective} than {noun}', 'noun1|adjective|noun2', 26, 'W000313', null, 'unverified', 'Composed by the agent. ກວ່າ W000313 after the adjective marks comparison; no separate word for ''than''. Batch words usable as nouns: ເຕົ່າ ກະຕ່າຍ ໝີ ຫີນ ໃບໄມ້ (also W000095 ໝາ W000286 ລົດ W000087 ແພງ W000088 ຖືກ). Examples S000002001 S000002002 S000002003 S000002004 S000002005 S000002023'),
  ('TPL27', '{noun}{number}{classifier}', '{number} {noun}(s)', 'noun|number|classifier', 27, 'W000047|W000097', null, 'unverified', 'Composed by the agent. Counting: noun + number + classifier (ໝາ ສອງ ໂຕ). App logic: the classifier slot is the noun''s classifier_word_id (specific or self; for measure nouns, the container word). For ''a/one'', ໜຶ່ງ usually follows the classifier (ໝາ ໂຕ ໜຶ່ງ); agent knowledge, unverified.'),
  ('TPL28', '{noun}{classifier}{demonstrative}', 'this / that / which {noun}', 'noun|classifier|demonstrative', 28, 'W000016|W000050|W000283', null, 'unverified', 'Composed by the agent. Demonstratives ນີ້/ນັ້ນ and the question word ໃດ follow the classifier: ໝາ ໂຕ ນີ້ ''this dog'', ປຶ້ມ ຫົວ ໃດ? ''which book?''. App logic: classifier slot = the noun''s classifier_word_id.'),
  ('TPL29', '{noun}{classifier}{adjective}', 'the {adjective} {noun} (singling one out)', 'noun|classifier|adjective', 29, 'W000089|W000090', null, 'unverified', 'Composed by the agent. A classifier before the adjective picks out one item among several: ລົດ ຄັນ ໃຫຍ່ ''the big car''. Without the classifier (ລົດໃຫຍ່) it is a plain description. App logic: classifier slot = the noun''s classifier_word_id.'),
  ('TPL30', '{verb}{number}{event_counter}', '{verb} {number} times', 'verb|number|event_counter', 30, 'W000324|W000323', null, 'unverified', 'Composed by the agent. Events are counted after the verb with ເທື່ອ or ຄັ້ງ: ໄປ ສອງ ເທື່ອ ''went twice''. This is the verb-side counterpart of noun classifiers; it is not stored per verb.')
